CREATE TABLE IF NOT EXISTS visual_ai_projects(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL,name TEXT NOT NULL DEFAULT 'Visual projekat',brand_id BIGINT NULL,status TEXT NOT NULL DEFAULT 'draft',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE TABLE IF NOT EXISTS visual_ai_assets(id BIGSERIAL PRIMARY KEY,project_id BIGINT REFERENCES visual_ai_projects(id) ON DELETE CASCADE,user_id BIGINT NOT NULL,asset_type TEXT NOT NULL,prompt TEXT,provider TEXT,status TEXT NOT NULL DEFAULT 'draft',source_asset_id BIGINT NULL,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE TABLE IF NOT EXISTS visual_ai_variants(id BIGSERIAL PRIMARY KEY,asset_id BIGINT REFERENCES visual_ai_assets(id) ON DELETE CASCADE,variant_no INT NOT NULL,prompt TEXT,format TEXT,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE TABLE IF NOT EXISTS visual_ai_jobs(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL,project_id BIGINT NULL,job_type TEXT NOT NULL,provider TEXT,status TEXT NOT NULL DEFAULT 'queued',input JSONB NOT NULL DEFAULT '{}'::jsonb,output JSONB NOT NULL DEFAULT '{}'::jsonb,error TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),started_at TIMESTAMPTZ NULL,completed_at TIMESTAMPTZ NULL);CREATE INDEX IF NOT EXISTS idx_visual_ai_assets_user ON visual_ai_assets(user_id,created_at DESC);CREATE INDEX IF NOT EXISTS idx_visual_ai_jobs_status ON visual_ai_jobs(status,created_at);